  if (act === 'complete') {
    userMessage = customPrompt || '';
  } else if (act === 'polish') {
    userMessage = customPrompt || '';
  } else if (act === 'fix') {
    userMessage = customPrompt || '';
  } else if (act === 'translate') {
    userMessage = customPrompt || '';
  } else {
    userMessage = customPrompt || '';
  }

