function readAiCustomHeaders() {
  const raw = $('ai-headers') ? $('ai-headers').value.trim() : '';
  if (!raw) return {};
  const parsed = JSON.parse(raw);
  if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') {
    throw new Error('请求头必须是 JSON 对象');
  }
  return parsed;
}

